{
 "command": "make test-fast 2>&1 | tail -40",
 "description": "Run fast test suite"
}

{
 "command": "cat tests/fxdata.py; cat Makefile; grep -rn \"LEDGERLINE_FX_FIXTURES\" . --exclude-dir=.git | head; ls",
 "description": "Inspect fixture loader and config"
}

{
 "mode": "filter",
 "query": "FX fixtures LEDGERLINE_FX_FIXTURES"
}

{
 "command": "LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -30",
 "description": "Rerun fast tests with FX fixtures path"
}

{
 "command": "sed -n 1,30p docs/testing.md; ls tests tests/fixtures 2>&1; git log --stat --oneline | head -30; ls scripts",
 "description": "Look for the missing fixtures"
}

{
 "command": "cat scripts/gen_fx_fixtures.py; ls -la tests/fixtures/fx",
 "description": "Read fixture generator script"
}

{
 "command": "python scripts/gen_fx_fixtures.py && LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -30; git status --short",
 "description": "Generate FX fixtures and rerun fast tests"
}

